mapper.select:
SELECT id, defaultAddressId, userName, account, phone, `describe`, email, balance,
       avatarPath, level, vipCreateTime, createTime, `delete`, uploadTime,
       uploadBackground, uploadGoods, updateAvatar
FROM user

    AND id = #{entity.id}
    AND defaultAddressId = #{entity.defaultAddressId}
    AND userName = #{entity.userName}
    AND account = #{entity.account}
    AND phone = #{entity.phone}
    AND `describe` = #{entity.describe}
    AND email = #{entity.email}
    AND balance = #{entity.balance}
    AND avatarPath = #{entity.avatarPath}
    AND level = #{entity.level}
    AND vipCreateTime = #{entity.vipCreateTime}
    AND createTime = #{entity.createTime}
    AND `delete` = #{entity.delete}
    AND uploadTime = #{entity.uploadTime}
    AND uploadBackground = #{entity.uploadBackground}
    AND uploadGoods = #{entity.uploadGoods}
    AND updateAvatar = #{entity.updateAvatar}
